import{_ as o,o as t,c as r,a2 as i}from"./chunks/framework.BTLSZHNB.js";const p=JSON.parse('{"title":"takoform_worker_version","description":"Worker Version (edge.forms.takoform.com/v1alpha1, role revision).","frontmatter":{"page_title":"takoform_worker_version Resource - takoform","subcategory":"Edge Platform Family","description":"Worker Version (edge.forms.takoform.com/v1alpha1, role revision)."},"headers":[],"relativePath":"docs/resources/worker_version.md","filePath":"docs/resources/worker_version.md"}'),a={name:"docs/resources/worker_version.md"};function n(s,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="takoform-worker-version" tabindex="-1">takoform_worker_version <a class="header-anchor" href="#takoform-worker-version" aria-label="Permalink to &quot;takoform_worker_version&quot;">​</a></h1><p>Immutable executable snapshot of one Module Worker: a bundle, the handlers its module exports, non-secret vars, and the typed capability bindings the code may use. A change is a new Worker Version; traffic moves only through Worker Deployments. The runtime this code runs on is not a field of this Form: it is fixed by the worker.runtime@1.0.0 contract the Module Worker identity provides, so a version carries no compatibility date and no compatibility flag (decision 0019).</p><p>This is a <code>revision</code> resource: an immutable snapshot. It is create-only — every desired attribute forces replacement, and rollback means pointing a deployment at an earlier revision, never editing this one.</p><p>This resource speaks the Host API v1alpha3 lane and requires provider v2.1.0 or later (source candidate; not yet published). The configured host selects and operates the concrete backend; no attribute names a vendor, target, credential, price, or implementation. See the <a href="../../examples/resources/takoform_worker_version/resource.tf">complete example</a>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>name</code> (String, required, forces replacement) — Portable resource name (<code>metadata.name</code>).</li><li><code>worker</code> (String, required, forces replacement) — Module Worker identity this version belongs to. Set the name of the target <code>ModuleWorker</code> resource.</li><li><code>bundle</code> (String, required, forces replacement) — Worker Bundle carrying the exact module bytes this version executes. Set the name of the target <code>WorkerBundle</code> resource.</li><li><code>handlers</code> (Set of String, required, forces replacement) — Module event handlers this version exports, from the closed vocabulary the worker.runtime@1.0.0 contract defines. A host rejects a handler that contract does not define, and rejects an attachment whose event kind is not declared here. One of <code>fetch</code>, <code>scheduled</code>, <code>queue</code>.</li><li><code>vars_json</code> (String, optional, forces replacement) — Non-secret configuration values projected into the module environment. Sensitive material never enters portable state. Omitting it projects no variable. Authored as one JSON object string (for example <code>jsonencode({...})</code>); the provider sends the parsed object. Defaults to the empty object <code>{}</code>.</li><li><code>kv_bindings</code> (List of Object, optional, forces replacement) — Typed module-worker.edge-kv bindings projecting the edge.kv API under JavaScript identifier names. Omitting it declares no such binding. Each entry declares <code>name</code> (a JavaScript identifier) and <code>target_name</code> (the target <code>EdgeKVNamespace</code> resource name); the wire carries the typed <code>resource</code> reference. Defaults to the empty list <code>[]</code>.</li><li><code>bucket_bindings</code> (List of Object, optional, forces replacement) — Typed module-worker.object-bucket bindings projecting the edge.objects API. Omitting it declares no such binding. Each entry declares <code>name</code> (a JavaScript identifier) and <code>target_name</code> (the target <code>ObjectBucket</code> resource name); the wire carries the typed <code>resource</code> reference. Defaults to the empty list <code>[]</code>.</li><li><code>sqlite_bindings</code> (List of Object, optional, forces replacement) — Typed module-worker.sqlite bindings projecting the edge.sql API. Omitting it declares no such binding. Each entry declares <code>name</code> (a JavaScript identifier) and <code>target_name</code> (the target <code>SQLiteDatabase</code> resource name); the wire carries the typed <code>resource</code> reference. Defaults to the empty list <code>[]</code>.</li><li><code>queue_producer_bindings</code> (List of Object, optional, forces replacement) — Typed module-worker.queue-producer bindings projecting only send and sendBatch. Omitting it declares no such binding. Each entry declares <code>name</code> (a JavaScript identifier) and <code>target_name</code> (the target <code>AtLeastOnceQueue</code> resource name); the wire carries the typed <code>resource</code> reference. Defaults to the empty list <code>[]</code>.</li><li><code>service_bindings</code> (List of Object, optional, forces replacement) — Typed module-worker.service bindings projecting worker.service fetch toward another Module Worker. Omitting it declares no such binding. Each entry declares <code>name</code> (a JavaScript identifier) and <code>target_name</code> (the target <code>ModuleWorker</code> resource name); the wire carries the typed <code>resource</code> reference. Defaults to the empty list <code>[]</code>.</li><li><code>required_sensitive_vars</code> (Set of String, optional, forces replacement) — Names of sensitive values this version requires the host to supply out-of-band. Only the names are portable state; values travel through each host&#39;s own sealed path. Omitting it requires no sensitive value. Defaults to the empty list <code>[]</code>.</li><li><code>space</code> (String, optional, forces replacement) — Exact opaque SpaceID; overrides the provider default.</li><li><code>create_timeout</code> / <code>delete_timeout</code> (String, optional) — Go durations bounding each operation (defaults <code>20m</code> / <code>30m</code>). There is no <code>update_timeout</code>: this Form declares no update capability. Changing only these provider-side timeouts is applied in place without any host call.</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>uid</code> — host-issued immutable resource identity; delete and re-create yields a new UID.</li><li><code>generation</code> — desired-state generation; increments only when the portable desired spec changes; this Form declares no update capability — every desired attribute forces replacement instead.</li><li><code>revision</code> — representation revision; increments whenever the representation changes — a spec-changing update, new status, or new outputs. Deletes fence on it via <code>If-Match</code>.</li><li><code>conditions</code> — the complete status condition list the host reports, in its order. Each entry carries <code>type</code> (the closed <code>Ready</code> / <code>Reconciling</code> / <code>Degraded</code> / <code>Drifted</code> / <code>Blocked</code> / <code>Deleting</code> vocabulary), <code>status</code> (<code>True</code> / <code>False</code> / <code>Unknown</code>), the closed portable <code>reason</code>, an optional <code>message</code>, an optional non-portable <code>host_reason</code> naming exactly what is wrong, the <code>observed_generation</code> the status reflects, and <code>last_transition_time</code>. Conditions are host-rendered state: they change when this resource changes AND when a resource it depends on changes, with no desired spec changing anywhere, so they are read-only and a configuration must not assert them.</li><li><code>ready</code> — derived convenience: true when <code>conditions</code> carries the closed <code>Ready</code> condition with status <code>True</code>. Read <code>conditions</code> for the reason it is not.</li><li><code>outputs_json</code> — the WHOLE <code>status.outputs</code> document, JSON-serialized. This Form declares no <code>outputSchema</code>, so a conforming host omits <code>status.outputs</code> entirely and this attribute is <code>&quot;{}&quot;</code>. It stays declared because a host may publish a value no contract describes, and an undescribed value must still be reachable rather than silently dropped.</li><li><code>form_api_version</code>, <code>form_kind</code>, <code>form_definition_version</code>, <code>form_schema_digest</code> — the exact immutable FormRef this state is bound to; reads dispatch on it.</li><li><code>form_package_digest</code> — audit-only package provenance; never part of resource identity, queries, or fences.</li><li><code>relation_drift_reason</code> — internal recovery only: <code>ExternalChange</code> or <code>DependencyMissing</code> while the host reports that a resource this one references was replaced or removed out of band, null otherwise. A refresh reports the break as a warning and keeps the resource in state; the next plan then proposes replacing this resource, because this Form declares no in-place update and a host refuses every apply to the existing one. It is provider-side recovery bookkeeping — no portable wire member carries it — and configurations must not depend on it.</li><li><code>pending_operation_id</code> — internal recovery only: the host operation id of a mutation the host accepted but that did not reach a terminal state before the operation deadline, null in steady state. A refresh consults it before it reads the resource, and it is cleared only once that operation settles. It is not resource identity and configurations must not depend on it.</li></ul><h2 id="state-continuity" tabindex="-1">State continuity <a class="header-anchor" href="#state-continuity" aria-label="Permalink to &quot;State continuity&quot;">​</a></h2><ul><li><strong>Reads dispatch on the recorded FormRef.</strong> <code>WorkerVersion</code> state is addressed under the exact <code>form_*</code> identity it records, not under this build&#39;s default create ref, so a resource created before the Form line advanced stays addressable as itself. An identity this provider build carries no codec for is a hard error naming that identity and the ones the build does carry; the provider never substitutes another exact FormRef, because a substituted query&#39;s &quot;not found&quot; is indistinguishable from deletion.</li><li><strong>A changed <code>uid</code> is an error, and state is kept.</strong> When the host serves a different <code>uid</code> under the recorded name, the resource this state was applied against is gone and something re-used its name. The provider reports a hard error naming both uids and keeps the resource in state. It does not re-bind — that would adopt a resource you never applied — and it does not remove state, which would make the next apply fail against the resource that does exist, with no plan left to repair it. Resolve it by importing the new incarnation explicitly, restoring the prior one, or deleting the host-side replacement.</li><li><strong>An unfinished mutation is resumed, not re-created.</strong> When <code>pending_operation_id</code> is set, a refresh asks the host about that operation before it reads the resource. While the operation is still running the resource may legitimately not exist yet, so its absence is not treated as deletion and the marker survives; a terminal success is verified against the exact identity and settles state; a terminal failure or an expired operation record defers to an exact read of the resource, which decides. Refresh again once the host settles.</li></ul><h2 id="accepted-bindings" tabindex="-1">Accepted bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted bindings&quot;">​</a></h2><ul><li><code>module-worker.edge-kv@1.0.0</code></li><li><code>module-worker.object-bucket@1.0.0</code></li><li><code>module-worker.sqlite@1.0.0</code></li><li><code>module-worker.queue-producer@1.0.0</code></li><li><code>module-worker.service@1.0.0</code></li></ul><p>Outward capability use is a typed binding held by this revision; inward activation (routes, domains, cron, queue consumption) is a separate attachment resource. The two are never merged.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_version.example NAME</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_version.example SPACE/NAME</span></span></code></pre></div><p>Both short forms bind state to this provider build&#39;s default create FormRef. To adopt a resource created under an EARLIER definition version of this Form, name the exact identity instead. The import ID is then one JSON object — not a delimiter-joined string, because a SpaceID is opaque UTF-8 whose only forbidden character is <code>/</code>, so no separator can escape it safely:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_version.example \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &#39;{&quot;space&quot;:&quot;prod&quot;,&quot;apiVersion&quot;:&quot;edge.forms.takoform.com/v1alpha1&quot;,&quot;kind&quot;:&quot;WorkerVersion&quot;,&quot;definitionVersion&quot;:&quot;0.1.0&quot;,&quot;schemaDigest&quot;:&quot;sha256:…&quot;,&quot;name&quot;:&quot;…&quot;}&#39;</span></span></code></pre></div><p><code>space</code> is optional and falls back to the provider default; the four FormRef members are all-or-nothing. An identity this provider build carries no codec for is refused, naming the identities it does carry — it is never silently rebound to the default.</p>`,18)])])}const m=o(a,[["render",n]]);export{p as __pageData,m as default};
